{s:QZ,k:'pq',term:'Question 2',lv:'A',n:2,q:"Helium (γ = 1.67) from a line at 290 K fills an insulated empty tank. Find the final temperature.",say:'Question two. Helium, gamma one point six seven, fills an insulated empty tank from a line at two hundred ninety kelvin. Find the final temperature.',cues:{k:'Question two',q:'Helium, gamma one'},pause:3.4},
{s:QZ,k:'pa',term:'Answer 2',lv:'A',n:2,q:"Helium (γ = 1.67) from a line at 290 K fills an insulated empty tank. Find the final temperature.",say:'Empty, insulated, no work: the final internal energy equals the line enthalpy, so the final temperature is gamma times the line temperature. One point six seven times two hundred ninety: four hundred eighty-four kelvin.',cues:{fk:'Empty, insulated, no',k1:'Empty, insulated, no',k1b:'so the final',k2:'One point six',k2b:'four hundred eighty-four'},calc:{f:[`T₂ = γT${TH_sub('i')}`],hint:'V and p₂ do not matter',fk:'fk',steps:[["Balance",[`m₁ = 0, Q = W = 0: u₂ = h${TH_sub('i')}`,`T₂ = γT${TH_sub('i')}`],["k1","k1b"]],["Final temperature",["T₂ = 1.67 × 290","T₂ = 484 K"],["k2","k2b"]]],live:[0,1]}},
{s:QZ,k:'pq',term:'Question 3',lv:'N',n:3,q:"Show that the gas left in an insulated tank during discharge follows the reversible adiabatic law.",say:'Question three. Show that the gas left in an insulated tank during discharge follows the reversible adiabatic law.',cues:{k:'Question three',q:'Show that the'},pause:3.4},
{s:QZ,k:'pa',term:'Answer 3',lv:'N',n:3,q:"Show that the gas left in an insulated tank during discharge follows the reversible adiabatic law.",say:'Each small mass that leaves carries enthalpy out of the stored energy. For an ideal gas, that ties temperature to mass. Put in the gas law: the temperature ratio is the pressure ratio to the power gamma minus one, over gamma.',cues:{a1:'Each small mass',a2:'For an ideal',a3:'Put in the',a4:'the temperature ratio'},al:[['d(mu) = h dm gives mcᵥ dT = RT dm','a1'],['so dT/T = (γ − 1) dm/m, and T ∝ mᵞ⁻¹','a2'],['With m = pV/(RT): Tᵞ ∝ pᵞ⁻¹','a3'],['so T₂/T₁ = (p₂/p₁) to the power (γ − 1)/γ','a4']],vis:(c,u,b)=>{
 /* T against p for the second worked example: T = 400 (p/1000)^0.2857, computed points */
 const X=p=>90+(p-150)/(1050-150)*500, Y=T=>420-(T-240)/(410-240)*330;
 const pts=[]; for(let p=1000;p>=200;p-=50) pts.push([p,400*Math.pow(p/1000,0.4/1.4)]);
 let s=TH_L(90,60,90,420,TH_DARK,3)+TH_L(90,420,600,420,TH_DARK,3)+TH_T(80,54,'T (K)',{fs:22,fw:800,a:'end'})+TH_T(345,480,'p (kPa)',{fs:22,fw:800,a:'middle'});
 [250,300,350,400].forEach(T=>{s+=TH_L(84,Y(T).toFixed(1),90,Y(T).toFixed(1),TH_DARK,2)+TH_T(78,(Y(T)+7).toFixed(1),T,{fs:20,a:'end',fill:TH_GREY})});
 [200,600,1000].forEach(p=>{s+=TH_L(X(p).toFixed(1),420,X(p).toFixed(1),426,TH_DARK,2)+TH_T(X(p).toFixed(1),448,p,{fs:20,a:'middle',fill:TH_GREY})});
 s+=g('pop',tk(c,'a1'),TH_tank(380,270,120,80,TH_COLD,BLU)+TH_T(440,318,'T falls',{fs:22,fw:800,a:'middle',fill:BLU})+TH_arrow(502,300,570,280,BLU,4)+TH_T(440,385,'gas leaves',{fs:22,fw:700,a:'middle',fill:TH_GREY}));
 s+=g('pop',tk(c,'a2'),`<polyline points="${pts.map(([p,T])=>X(p).toFixed(1)+','+Y(T).toFixed(1)).join(' ')}" fill="none" stroke="${BLU}" stroke-width="5"/>`+pts.map(([p,T])=>`<circle cx="${X(p).toFixed(1)}" cy="${Y(T).toFixed(1)}" r="4" fill="${BLU}"/>`).join(''));
 const [p1,T1]=pts[0],[p2,T2]=pts[pts.length-1];
 s+=g('pop',tk(c,'a4'),`<circle cx="${X(p1).toFixed(1)}" cy="${Y(T1).toFixed(1)}" r="10" fill="${ORG}"/><circle cx="${X(p2).toFixed(1)}" cy="${Y(T2).toFixed(1)}" r="10" fill="${GRN}"/>`+TH_T((X(p1)-14).toFixed(1),(Y(T1)+36).toFixed(1),'1: 400 K',{fs:22,fw:800,a:'end',fill:ORG})+TH_T((X(p2)+22).toFixed(1),(Y(T2)-24).toFixed(1),'2: 252.6 K',{fs:22,fw:800,fill:GRN}));
 return s}},
{s:LS,k:'figs',term:'Your notes',title:'For your notes',say:'Your free notes are the PDF in the description. Redraw the filling tank and the two cups, then redo all three examples.',cues:{t:'Your free notes',f:'Redraw the filling'},tags:[["Free notes for this lesson (PDF)", "link in the description"], ["In this lesson", "Unsteady flow processes: filling and emptying of vessels; Limitations of the first law"], ["Key terms and glossary", "at the end of the notes"]],figs:[["Filling an empty insulated tank", "Each kilogram of line air brings u = 215.4 kJ plus 86.1 kJ of flow work, h = 301.5 kJ; it all stays as internal energy, so the tank ends at 420 K from a 300 K line."], ["The cooling cup, both ways", "46.0 kJ passes from the water to the room or back, and both balance energy; only cooling raises total entropy (by 0.0127 kJ/K), so only cooling happens."]],note:"Sources your free notes draw on: P. K. Nag (Engineering Thermodynamics: the chapters on the first law and on its application to flow processes.)"},
{s:OUT,k:'outro',term:'Outro',say:'So remember: crossing mass carries enthalpy, a filled tank ends at gamma times the line temperature, and the first law never points the way. Next time, heat engines, refrigerators and heat pumps. See you there!',cues:{f:'So remember',w1:'crossing mass carries',w2:'a filled tank',w3:'and the first',n:'Next time',s:'See you there'},words:[['MASS CARRIES h','BLU','w1'],[`T₂ = γT${TH_sub('i')}`,'ORG','w2'],['A LEDGER, NOT A COMPASS','GRN','w3']],next:["NEXT TIME", "Next lesson", "Heat engines, refrigerators and heat pumps", "book"],end:'See you there!'}
